import csv,json,collections as C
from pathlib import Path
P=Path(__file__).resolve().parent
def get(n):return json.loads((P/n).read_text())
def table(head,rows):
 return '\n'.join(['| '+' | '.join(head)+' |','|'+'|'.join('---' for _ in head)+'|']+['| '+' | '.join(str(x) for x in row)+' |' for row in rows])
def pct(x,n):return f'{100*x/n:.2f}%'
def ratio(f,n):return f'{f:,}/{n:,} ({pct(f,n)})' if n else '—'
def main():
 d=get('SUMMARY.json');ranges=d['inference'];by=d['by_source'];old=d['strict_original'];fresh=d['strict_fresh'];ss=by['all']['pet/summon'];a=ranges['all']
 v=ss['matches'];nn=ss['turns'];miss=nn-v
 zero=miss+a['unmapped food, no witness'];pin=json.loads((P.parent/'engine-pin-recover.json').read_text())
 assoc=list(csv.DictReader(open(P/'sell-action-rates.csv')));rates={(r['cohort'],r['turn_selection'],r['category'],r['name']):[int(r['misses']),int(r['attempted'])] for r in assoc if r['split']=='all'}
 def assoc_table(kind,names):
    rows=[]
    for n in names:
     cells=[ratio(*rates.get((co,'sell-heavy (2+)',kind,n),(0,0))) for co in ('original strict','new pet/summon','record-certified new')]
     rows.append([n,*cells])
    return table(['Seller' if 'seller' in kind else 'Action present','Originally strict','New candidate search','Independent-ID subset of new'],rows)
 def put(s):out.append(s.strip())
 out=[]
 put('# Recovering the 710 skipped Turtle shop turns')
 put(f'**{nn} of the 710 have representable pet/summon inputs on this pin. {v} of those {nn} reproduce the recorded endpoint ({pct(v,nn)}).** There are {miss} mapped turns with no matching assignment and seven additional turns whose consumed food enum has no native representation. Across all 710, **{zero} have no witness**. The fresh strict check reproduced **{fresh["all"]["reproduced"]:,}/{fresh["all"]["attempted"]:,} ({pct(fresh["all"]["reproduced"],fresh["all"]["attempted"])})** on 300 separate matches.')
 put(f'Only **{a["unique"]}** turns had a single observed assignment. On {a["small 2-5"]} there were 2–5 assignments and on {a["broad 6+"]} there were six or more. All {v} count as reproduced on the requested fields. For most purposes a purchase screenshot is still valuable for the {a["small 2-5"]+a["broad 6+"]} multi-assignment turns. It would also supply independent verification for the singleton labels selected by the engine. [All 710 turn results](recover/turns.csv) · [All concrete passing assignments and replay seeds](recover/assignments.jsonl.gz)')
 put('## Coverage by match split')
 put(table(['Split','Original skips','Mapped inputs','One assignment','2–5 assignments','6+ assignments','Mapped with no witness','Unmapped food with no witness','Reproduced / mapped'],[
   [sp,by[sp]['all 710']['turns'],by[sp]['pet/summon']['turns'],*[ranges[sp].get(k,0) for k in ('unique','small 2-5','broad 6+','no candidate witnessed','unmapped food, no witness')],ratio(by[sp]['pet/summon']['matches'],by[sp]['pet/summon']['turns'])] for sp in ('dev','heldout','all')]))
 put(table(['Original skip reason','Turns','Now reproduced','No witness'],[[label,by['all'][key]['turns'],by['all'][key]['matches'],by['all'][key]['turns']-by['all'][key]['matches']] for label,key in [('Purchased/merged pet','unidentified purchased/merged pet'),('Referenced board pet after summon','unidentified referenced board pet after summon'),('Food enum 130/131','unmapped purchased food enum')]]))
 put(f'The newly modelable failure rate was **{ratio(miss,nn)}**. The earlier strict reference was 6,673/6,735 successes (99.08%). Under this pin those same turns scored **{old["all"]["reproduced"]:,}/6,735 ({pct(old["all"]["reproduced"],6735)} success, {pct(6735-old["all"]["reproduced"],6735)} failure)**. One previously missed held-out turn passed. Every other strict status stayed the same. The recovered population contains more sales, and searching identities against the answer makes its score an **endpoint compatibility rate**. It is a different test of correctness from replaying known inputs.')
 put('## Which identities are independent of the engine result?')
 put('The raw records constrain the source UID, destination slot, explicit same-species merges, later board references, and gold. A normal purchase costs three regardless of species. The aggregate sale ledger sometimes isolates Pig after accounting for Swan, level, carried sale bonuses and other sales. Named Milk/Better Milk/Best Milk and Bread Crumbs receipts can constrain which buy stocked Milk or which sale stocked Crumbs. Those identifications rely on the recorded item and the published producer rule. They cannot independently validate that same producer rule. Simple Pills on known pets with a known perk can similarly determine a sole summoned species without consulting its simulated stats.')
 evidence=get('evidence-summary.json')
 def ec(sp,src,res):return sum(x['n'] for x in evidence[sp] if x['source']==src and x['result']==res)
 classes=['sale proceeds','named stock receipt + producer','Pill + documented summon/perk','terminal effects discriminate','engine reconstruction; no action/wallet competitor witnessed']
 put(table(['Basis for identification','Dev match / miss','Held-out match / miss','Total match / miss'],[[x]+[f"{ec(sp,x,'match')} / {ec(sp,x,'miss')}" for sp in ('dev','heldout','all')] for x in classes]))
 cert_match=sum(ec('all',x,'match') for x in classes[:3]);cert_miss=sum(ec('all',x,'miss') for x in classes[:3]);ef=ec('all',classes[3],'match');en=ec('all',classes[4],'match')
 put(f'**{cert_match+cert_miss} identities were fixed before testing the endpoint.** {cert_match} matched, {cert_miss} missed ({pct(cert_miss,cert_match+cert_miss)} failure). Another **{ef+en} singleton matches depended on native reconstruction**. For {ef} there is a concrete *different* assignment that completes the recorded actions at the right prices and ends with the right wallet, but differs on the recorded terminal fields. For {en}, the recorded constraints alone allow alternatives; the diagnostic found no second action-and-wallet-compatible assignment. Treat neither group as independent evidence for the fitted pet’s behavior. The remaining unique status is empirical within the tested RNG support. [Per-turn evidence classification and competing identities](recover/identity-evidence.csv) · [Input-side certificates](recover/input-certificates.jsonl)')
 put('For example, in dev match §01a1b2f1§, turn 6, both Ant and Beaver can be bought and sold with the correct wallet. Only Beaver gave the observed permanent stats among the tested assignments. In dev match §01a1f157§, turn 13, the two UIDs can be Duck and Beaver in either order. No choice between those two joint assignments is justified by the endpoint. A masked control hid the names of 173 otherwise observed, bought-and-sold pets, preserved their recorded frozen flags, and recomputed the input-side constraints. All 173 true names survived; 91 were uniquely predicted before simulating final stats. These controls test the pruning logic, not the identity of the genuinely hidden pets. [Masking control](recover/masked-controls.json)')
 put('## No-matching-candidate turns')
 nm=list(csv.DictReader(open(P/'no-match.csv')));reasons=sorted(set(x['category'] for x in nm))
 put(table(['Nearest diagnostic discrepancy','Dev','Held-out','Total'],[[s,sum(r['category']==s and r['split']=='dev' for r in nm),sum(r['category']==s and r['split']=='heldout' for r in nm),sum(r['category']==s for r in nm)] for s in reasons]))
 put('These groups describe one closest diagnostic execution or the first unusable input. They are not mutually exclusive explanations of the underlying code. The CSV includes the full match and seat IDs, first blocked action where available, example candidate, exact field deltas and real versus native wallet. Unknown RNG and the mapping of newly generated UIDs can both cause a miss. [All no-witness cases](recover/no-match.csv) · [Action sequences and snapshots](recover/negative.jsonl)')
 put('Three dev receipts isolate different issues:\n\n- **Ram sale value.** In §01a1a19a§ turn 9, Sheep #24 (one XP) merged into Sheep #142, reaching level 2. It was pilled. The only sales were both new Rams and the level-one Giraffe #63. §GoGa=5§ gives **four gold for the Ram pair** after the Giraffe’s one. Native income was three total, one per Ram, and the next real roll was unaffordable. No seller-species guess is needed here. The aggregate receipt establishes the pair’s proceeds; it does not contain separate payouts for each sale.\n- **Scorpion shop perk.** In §01a20136§ turn 10, a stock receipt identifies the missing Cow. Board and wallet match. Frozen Scorpion #159 is bare in the real shop and has Peanut in the native shop. An alternative pet for the missing buy does not explain the frozen-slot difference.\n- **Residual HP.** In §01a1e5bb§ turn 10, Milk constrains the missing purchase to Cow. The closest native Tiger finishes 6/4 with Melon; the real Tiger finishes 6/6 with Melon. A level-two Rabbit and a Pill are present. The terminal discrepancy is clear; the log does not localize the trigger that lost the two HP.')
 put('## Food IDs 130 and 131')
 put('The seven turns contain **four pairs of enum 130 and three pairs of enum 131**, each pair consumed by a targeted Type 8 action. All 14 raw §Spell§ objects include §Enu§, an item UID, §Pow: 0§, §Sto: false§ and §Buff: true§. **All omit §Pri§**, decoding to price zero; the turn spending also reconciles at zero. None contains a display name or explicit attack/health magnitude. Each pair is the next two food purchases after Chocolate. Six Chocolate recipients are independently named Cows. The seventh is an unnamed purchase constrained to Cow by earlier ordinary Milk receipts.')
 put('The level pattern is consistent across all seven: enum **130** follows Chocolate taking its recipient from XP 0 to 1 (still level 1); **131** follows XP 1 to 2 (level 2). The clean enum-130 Elephant case gains **+2 permanent attack and +0 HP** over two uses. In the enum-131 Dodo case it gains **+8/+0** over two uses with a level-one Cat. Together with the Badger/Monkey case these observations support **+1/+0** and **+2/+0** per item before modifiers. The names “Chocolate Milk” or “Better Chocolate Milk” would be guesses. The recorded fact is a distinct, free Cow/Chocolate-associated buff with different enum IDs from ordinary Milk.')
 put('I tried 24 represented native food-name/strength aliases per unmapped enum, enforcing the observed price, source UID and natural stock generation. None yielded a joint witness. In §01a19d3e§ turn 9, a Chocolate on the existing Cow is followed by casts from UIDs #141 and #140. The native shop has minted only through #139 after the Chocolate. Substituting a name for #141 cannot create it. These seven remain unsupported inputs; forcing two extra foods into stock would have tested a modified engine. [Raw spell fields, recipients and before/after stats](recover/food-receipts.json)')
 put('## Sales and actions')
 put('**Sell-heavy means at least two Type 9 sales in one seat-turn.** All cells below show **misses / attempted turns**, once per turn. Rows can overlap. A seller is attributed here only if named in the log/identity ledger or identified by the pre-endpoint certificate. A missing seller that fits a failing turn is not assigned an invented species. The independent-ID column is a subset of the new pet/summon column. [All rates by split, seller, action and sale count](recover/sell-action-rates.csv) · [Per-turn seller UIDs](recover/sell-turns.csv) · [Separate possible and necessary fitted sellers](recover/fitted-sellers.csv)')
 put(table(['Sale count','Originally strict','New pet/summon','Independent-ID subset'],[[w]+[ratio(*rates.get((co,w,'overall','(all)'),(0,0))) for co in ('original strict','new pet/summon','record-certified new')] for w in ('no sale','at least one sale','sell-heavy (2+)')]))
 put('### By action on sell-heavy turns')
 actions=sorted({x[3] for x in rates if x[2]=='action' and x[1]=='sell-heavy (2+)'})
 put(assoc_table('action',actions))
 put('### By sold species on sell-heavy turns')
 sellers=sorted({x[3] for x in rates if x[2]=='seller before endpoint' and x[1]=='sell-heavy (2+)'})
 put(assoc_table('seller before endpoint',sellers))
 put('For example, the Ram row concerns the whole turn containing a Ram sale. It is not a direct estimate of the probability that a single Ram sale is wrong. The alternative fitted-seller file counts how often a species is possible, or required somewhere among the hidden sales on all observed passing assignments. Those counts are deliberately separate from seller failure rates.')
 put('## Fresh strict comparison')
 put(table(['Fresh match split','Completed T≥2','Replayable','Skipped','Reproduced','Failure rate'],[[sp,f'{fresh[sp]["completed"]:,}',f'{fresh[sp]["attempted"]:,}',sum(fresh[sp]['skips'].values()),f'{fresh[sp]["reproduced"]:,}',ratio(fresh[sp]['attempted']-fresh[sp]['reproduced'],fresh[sp]['attempted'])] for sp in ('dev','heldout','all')]))
 put('The 300 fresh matches have **zero MatchId overlap** with the original 340. The unchanged strict parser and comparison used the same match-hash split and staged seed schedule. The fresh dataset was excluded from candidate inference, diagnostics and tuning. Fresh skips break down as 608 unnamed purchases/merges, 41 unresolved board references, nine unmapped foods, one missing start/end action and one unidentified purchased item. This is a shop endpoint comparison; the separately supplied 2.00% fresh battle number measures outcomes and survivors. [Fresh input counts](recover/fresh/corpus.json) · [Strict and inference summaries](recover/SUMMARY.json)')
 put('## Search contract and reproducibility')
 put(f'Current engine tree SHA-256: §{pin["sha256"]}§, the hash of its sorted per-file Python SHA-256 map. The audit used a read-only mount of the saved copy, with networking and CUDA disabled and all workers confined to CPUs 5–9 and 16. The engine code was not edited. [Exact source pin](engine-pin-recover.json) · [Pinned engine](pinned-recover)')
 put(f'The search treated a candidate as an assignment to **all** missing UIDs together. Ordinary pet offers use the unlocked pool, including rare Sloth as a possible observed override. Linked discovers must come from the next tier (capped at 6), have distinct siblings, and cannot both be purchased. The initial domain is a superset when a previous level-up might have created a reward; the native mint checks the role. The actions enforce purchase slot, same-species merging, sale legality, freezes, all later references and food prices. The wallet prunes impossible Pig combinations when sale levels are known. Named stock receipts constrain possible producers within a refresh interval. Each terminal witness matches board positions **and UIDs**, species, level, XP, permanent/temporary attack and HP, perk, frozen item details and wallet on the same execution.')
 put(f'At seed index zero the uncompressed pass tried **{d["concrete_seed0_vectors"]:,} individual purchase assignments** after input pruning, including one empty purchase vector on summon-only cases. It made {d["concrete_calls"]:,} native calls including food-alias and Spider alternatives. All implicated Spider choices were explored from the native tier-three pool. Other generated pets came from the native Pill, perk and summon chain. A separate pass on Pill turns also tested alternate UID bindings among simultaneously born pets, preserving their native species, stats and order.')
 put(f'Further seed passes revisited alternatives, including alternatives on turns that already had one match. Broad sets received a shorter refinement; rare/singleton sets were prioritized up to 1,024 seeds and outstanding zero-witness turns up to 8,192, with early exits for deterministic branches. For refinement only, same-tier nontriggering pets bought and immediately sold could share a trial when their slot/merge and discover constraints agreed. **Every retained assignment was then expanded and replayed concretely with its own named inputs.** The receipt file contains {d["matching_assignments"]:,} such assignments. Counts of matching assignments are witnessed lower bounds. In particular, “unique” does not prove another identity could never match on an untested RNG path. [Candidate engine](recover/infer.py) · [Search](recover/search.py) · [Concrete verification](recover/verify.py)')
 put('When an input-side freeze list followed a refresh, known newly generated ordinary pet pairs supplied tier-order constraints. Across 12,046 identified pairs there was one strict tier-order exception, the observed Sloth. The filter exempts Sloth and imposes no equal-tier UID order. It removed five candidate assignments without changing a turn’s category. Omitting Sloth entirely yields the same 680 reproduced turns and 516 singletons. Among the remaining matches, 35 have 2–5 native-pool assignments and 129 have six or more. No turn requires Sloth to pass. On the 23 mapped zero-witness turns, a sensitivity pass also removed the gold/stock-producer pruning while retaining recorded actions and endpoint checks. No additional witness was found under its smaller seed budget. [Offer-order check](recover/order_evidence.py) · [Relaxed-pruning results](recover/relaxation.jsonl)')
 put('The concrete single-seed pass already found witnesses for 560/710. Multi-seed and summon-branch refinement brought this to 680. Neither the 1,024-seed refinement on the remaining small sets nor the 8,192-seed follow-up on the residual zero-witness cases changed their status. The seven food turns remain outside the comparable pet/summon denominator. All raw-file hashes for the fresh corpus and the 23-hunk patch digest are preserved. [Provenance](recover/provenance.json) · [Replay one stored witness](recover/replay_one.py)')
 (P.parent/'REPORT-3.md').write_text('\n\n'.join(out).replace('§',chr(96))+'\n')
